// Shared limits used by the models, the REST controller and the socket handler.
// Keep the values the client also needs in sync with frontend/src/config.js.

// Room codes are generated by the server from an alphabet without look-alikes
// (no I, L, O, 0, 1). Eight characters gives about 850 billion combinations.
const ROOM_CODE_LENGTH = 8;
const ROOM_CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const ROOM_CODE_REGEX = /^[A-Z0-9]{8}$/;

const USERNAME_MAX_LENGTH = 20;
const PASSWORD_MAX_LENGTH = 100;

// Room lifetime, chosen by the host at creation and extendable up to the max.
const LIFETIME_OPTIONS_MINUTES = [10, 30, 60, 180, 1440];
const DEFAULT_LIFETIME_MINUTES = 60;
const MAX_LIFETIME_MINUTES = 1440;
const EXTEND_OPTIONS_MINUTES = [15, 60];

// When a room closes besides its timer running out.
//   host_leaves      the room closes when the host leaves
//   everyone_leaves  the room closes when the last person leaves
//   timer_only       only the timer or the host's "close room" button ends it
const END_POLICIES = ['host_leaves', 'everyone_leaves', 'timer_only'];
const DEFAULT_END_POLICY = 'host_leaves';

const SLOW_MODE_OPTIONS_SECONDS = [0, 5, 15, 60];
const BURN_OPTIONS_SECONDS = [0, 10, 60, 300];

// How long a dropped connection keeps its seat before the user counts as gone.
// Covers page refreshes, network switches and phones going to sleep.
const RECONNECT_GRACE_MS = 20000;

const HISTORY_LIMIT = 50;

// Messages are encrypted in the browser, so the server only sees base64
// ciphertext. A 2 MB file encrypts to roughly 2.7 MB of base64.
const MAX_CIPHERTEXT_LENGTH = 3000000;
const ROOM_STORAGE_CAP_BYTES = 20000000;
const SOCKET_MAX_BUFFER_BYTES = 4000000;

const MESSAGE_RATE = { max: 5, windowMs: 5000 };
const JOIN_FAIL_RATE = { max: 10, windowMs: 10 * 60 * 1000 };
const CREATE_RATE = { max: 10, windowMs: 60 * 1000 };
const LOOKUP_RATE = { max: 60, windowMs: 60 * 1000 };

module.exports = {
  ROOM_CODE_LENGTH,
  ROOM_CODE_ALPHABET,
  ROOM_CODE_REGEX,
  USERNAME_MAX_LENGTH,
  PASSWORD_MAX_LENGTH,
  LIFETIME_OPTIONS_MINUTES,
  DEFAULT_LIFETIME_MINUTES,
  MAX_LIFETIME_MINUTES,
  EXTEND_OPTIONS_MINUTES,
  END_POLICIES,
  DEFAULT_END_POLICY,
  SLOW_MODE_OPTIONS_SECONDS,
  BURN_OPTIONS_SECONDS,
  RECONNECT_GRACE_MS,
  HISTORY_LIMIT,
  MAX_CIPHERTEXT_LENGTH,
  ROOM_STORAGE_CAP_BYTES,
  SOCKET_MAX_BUFFER_BYTES,
  MESSAGE_RATE,
  JOIN_FAIL_RATE,
  CREATE_RATE,
  LOOKUP_RATE,
};
